"""Local read-only monitoring UI; independent of the Codex turn."""
import json,threading,time
from pathlib import Path
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
import psutil
H=Path(__file__).resolve().parent
def read(p):
    try:return json.loads(p.read_text(encoding='utf-8'))
    except (OSError,ValueError):return None
def status():
    state=read(H/'CAMPAIGN_STATUS.json') or {};policies={};checkpoints={}
    for name in ['B1','B3_A1']:
        live=read(H/'policies'/name/'LIVE_STATUS.json');final=read(H/'policies'/name/'FINAL_AIDC.json')
        policies[name]=dict(live=live,final_summary={k:final[k] for k in ['status','AC','timeline','metrics','total_runtime_seconds']} if final else None)
        checkpoints[name]=[{k:x.get(k) for k in ['checkpoint_seconds','actual_elapsed_seconds','P1','time_to_best_P1_seconds']} for p in sorted((H/'policies'/name/'checkpoints').glob('*.json')) if (x:=read(p))]
    for name in ['B2','B3_M1','B3_MF']:
        x=read(H/'policies'/name/'FINAL_MESS.json');policies[name]=dict(final_summary={k:x[k] for k in ['status','AC','metrics','wall_seconds']} if x else None)
    alive=False;memory=None
    try:
        pid=int((H/'CAMPAIGN_V2_PID.txt').read_text());p=psutil.Process(pid);alive=p.is_running();m=p.memory_info();memory=dict(RSS=m.rss,peak=getattr(m,'peak_wset',m.rss))
    except (OSError,ValueError,psutil.Error):pass
    return dict(state=state,alive=alive,memory=memory,policies=policies,checkpoints=checkpoints,updated=time.strftime('%Y-%m-%d %H:%M:%S'),preflight=bool((H/'PREFLIGHT_PASS.json').exists()),B0=read(H/'policies/B0/FINAL_INDEPENDENT_AC/AC_SUMMARY.json'))
PAGE='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>IEEE8500 실시간 모니터</title><style>body{background:#0c1521;color:#dce9f7;font:16px system-ui;margin:0;padding:30px}h1{font-size:27px;margin:0 0 8px}.muted{color:#93a7bc}.grid{display:grid;grid-template-columns:repeat(3,minmax(200px,1fr));gap:16px;margin:20px 0}.card{background:#162333;border:1px solid #2b3e53;border-radius:12px;padding:20px}.big{font-size:28px;font-weight:650;margin:8px 0}.ok{color:#70e1b2}progress{width:100%;height:18px;accent-color:#4cc9b0}table{width:100%;border-collapse:collapse;margin-top:12px}td,th{text-align:left;padding:10px;border-bottom:1px solid #2b3e53}th{color:#93a7bc;font-weight:500}.tag{padding:6px 11px;border-radius:20px;background:#1f3b3b;color:#86e7c1}.error{color:#ff9595;white-space:pre-wrap}.foot{font-size:13px;margin-top:20px;line-height:1.7} @media(max-width:850px){.grid{grid-template-columns:1fr}}</style><h1>IEEE8500 실시간 실행 모니터</h1><div class="muted">2025-05-21 · source 1.0400 · Vreg 123.5 V · α8500 0.50 · CAPBank3 OFF</div><div class="grid"><div class="card">현재 단계<div class="big" id="stage">연결 중</div><span id="health"></span></div><div class="card">검증된 incumbent P1<div class="big" id="p1">—</div><div class="muted">exact OpenDSS 96-slot AC</div></div><div class="card">진행 / 목표<div class="big" id="elapsed">—</div><progress id="bar" max="240" value="0"></progress></div></div><div class="grid"><div class="card">LP/MILP solve count<div class="big" id="solve">—</div></div><div class="card">Exact AC validation / incumbent 갱신<div class="big" id="ac">—</div></div><div class="card">메모리 RSS / OS peak<div class="big" id="ram">—</div></div></div><div class="card"><b>4-hour run checkpoints</b><table><thead><tr><th>Run</th><th>30 min</th><th>1 h</th><th>2 h</th><th>4 h</th></tr></thead><tbody id="checks"></tbody></table></div><div class="card" style="margin-top:16px"><b>Policy 결과</b><table><thead><tr><th>단계</th><th>상태</th><th>Final exact P1</th><th>Vmin / Vmax</th></tr></thead><tbody id="results"></tbody></table><div id="error" class="error"></div></div><div class="foot muted">Preflight: <span id="preflight">—</span> · 마지막 갱신: <span id="updated">—</span><br>5초마다 자동 갱신합니다. 이 화면을 닫아도 백그라운드 계산은 계속됩니다.<br>B1 4 h → B2 full MESS → B3 M1 → A1 4 h → MF. 기존 operating-point authority와 자원 scale은 변경하지 않습니다.</div><script>const el=id=>document.getElementById(id),num=x=>x==null?'—':Number(x).toLocaleString(),p1=x=>x==null?'—':Number(x).toFixed(12);async function update(){try{let d=await(await fetch('/status',{cache:'no-store'})).json(),s=d.state.status||'UNKNOWN',name=s.startsWith('B3_A1')?'B3_A1':'B1',v=d.policies[name].live,active=s.startsWith('B1_')||s.startsWith('B3_A1_');el('stage').textContent=s.replace('_14400_SECOND_CONTINUOUS_SEARCH',' · 4 h');el('health').innerHTML=d.alive?'<span class="tag">실행 중</span>':s==='COMPLETE'?'<span class="tag">완료</span>':'<span class="error">프로세스 확인 필요</span>';el('p1').textContent=active&&v?p1(v.P1):'—';el('elapsed').textContent=active&&v?(v.elapsed_seconds/60).toFixed(1)+' / 240 min':'단계별 실행 중';el('bar').value=active&&v?v.elapsed_seconds/60:0;let m=v&&v.metrics;el('solve').textContent=active&&m?num(m.neighborhood_LP_MILP.count):'—';el('ac').textContent=active&&m?num(m.exact_AC_validation.count)+' / '+num(v.incumbent_updates):'—';el('ram').textContent=d.memory?(d.memory.RSS/2**30).toFixed(2)+' / '+(d.memory.peak/2**30).toFixed(2)+' GiB':'—';el('checks').innerHTML=['B1','B3_A1'].map(n=>'<tr><td>'+n+'</td>'+[1800,3600,7200,14400].map(t=>{let c=d.checkpoints[n].find(x=>x.checkpoint_seconds===t);return '<td>'+p1(c&&c.P1)+'</td>'}).join('')+'</tr>').join('');el('results').innerHTML=['B0','B1','B2','B3_M1','B3_A1','B3_MF'].map(n=>{let f=n==='B0'?d.B0:d.policies[n].final_summary,a=n==='B0'?f:f&&f.AC;return '<tr><td>'+n+'</td><td>'+(a?'AC PASS':s.startsWith(n+'_')?'진행 중':'대기')+'</td><td>'+p1(a&&a.max_phase_line_loading_pu)+'</td><td>'+(a?a.Vmin_pu.toFixed(6)+' / '+a.Vmax_pu.toFixed(6):'—')+'</td></tr>'}).join('');el('preflight').textContent=d.preflight?'PASS':'검사 중';el('updated').textContent=d.updated;el('error').textContent=d.state.error?d.state.error+': '+d.state.message:''}catch(e){el('updated').textContent='연결 재시도 중: '+e.message}}update();setInterval(update,5000)</script></html>'''
class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        data=json.dumps(status()).encode() if self.path.startswith('/status') else PAGE.encode();self.send_response(200);self.send_header('Content-Type','application/json; charset=utf-8' if self.path.startswith('/status') else 'text/html; charset=utf-8');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(data)
    def log_message(self,*args):pass
if __name__=='__main__':ThreadingHTTPServer(('127.0.0.1',8509),Handler).serve_forever()
